import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String s = Integer.toBinaryString(n);
        int bittalar = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') bittalar++;
        }
        System.out.println(s + " " + bittalar);
    }
}

solution.cpp:
#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;
    string s;
    int t = n;
    while (t > 0) {
        s = char('0' + t % 2) + s;
        t /= 2;
    }
    int bittalar = 0;
    for (char c : s) {
        if (c == '1') bittalar++;
    }
    cout << s << " " << bittalar << endl;
    return 0;
}
